import React from "react";

export default function TaskCard({
  task,
  onEdit,
  onDelete,
  onToggleComplete,
}) {
  const badgeColor =
    task.priority === "High"
      ? "bg-red-500"
      : task.priority === "Medium"
      ? "bg-yellow-500"
      : "bg-green-500";

  return (
    <div
      className={`p-4 rounded-lg shadow flex items-start justify-between border 
      ${task.completed ? "opacity-60 line-through" : "bg-white"}`}
    >
      <div className="flex items-start gap-3 flex-1">
        <input
          type="checkbox"
          checked={task.completed}
          onChange={onToggleComplete}
          className="mt-1 w-4 h-4"
        />

        <div className="flex-1">
          <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold">{task.title}</h3>
            <span
              className={`px-2 py-1 text-xs text-white rounded ${badgeColor}`}
            >
              {task.priority}
            </span>
          </div>

          {task.category && (
            <p className="text-xs text-gray-500 mt-1">{task.category}</p>
          )}

          {task.description && (
            <p className="text-sm text-gray-700 mt-2">{task.description}</p>
          )}
        </div>
      </div>

      {/* Buttons */}
      <div className="flex gap-2 ml-4">
        <button
          onClick={onEdit}
          className="px-3 py-1 bg-blue-500 text-white rounded text-sm hover:bg-blue-600"
        >
          Edit
        </button>

        <button
          onClick={onDelete}
          className="px-3 py-1 bg-red-500 text-white rounded text-sm hover:bg-red-600"
        >
          Delete
        </button>
      </div>
    </div>
  );
}
